import logging
from taf.transport.ssh import ssh


log = logging.getLogger(__name__)
ssh = ssh()


def create_dir(ssh_alias, path):
    log.info('Creating remote directory... ({})'.format(path))
    ssh.send_command('if exist {} (echo yes) else (echo no && mkdir {})'.format(path, path), connection=ssh_alias)
    assert_msg = 'The filename, directory name, or volume label syntax is incorrect'
    error_msg = ssh.read_error(connection=ssh_alias)
    print(error_msg)
    if assert_msg in error_msg:
        print ('Remote directory creation is failed. Error_Msg ({}) '.format(error_msg))
        raise Exception(error_msg)


def copy_file_to_remote_path(ssh_alias, filename, remote_path):
    log.info('Copying ({}) to remote path({})'.format(filename, remote_path))
    ssh.upload_file(local_path=filename, remote_path=remote_path, connection=ssh_alias)


def download_file_from_remote_path(ssh_alias, filename, remote_path):
    log.info('Copying ({}) from remote path({})'.format(filename, remote_path))
    ssh.download_file(remote_path=remote_path, local_path=filename, connection=ssh_alias)